package com.railreserve.model;

public final class Booking {
    private final long id,seatId,journeyId; private final String pnr,trainNumber,trainName,source,destination,journeyDate,departure,arrival,passengerName,gender,coach,status,bookedAt,cancelledAt; private final int arrivalDayOffset,age,seatNumber,fare; private final TravelClass travelClass;
    public Booking(long id,String pnr,long seatId,long journeyId,String trainNumber,String trainName,String source,String destination,String journeyDate,String departure,String arrival,int arrivalDayOffset,String passengerName,int age,String gender,String coach,int seatNumber,TravelClass travelClass,int fare,String status,String bookedAt,String cancelledAt){this.id=id;this.pnr=pnr;this.seatId=seatId;this.journeyId=journeyId;this.trainNumber=trainNumber;this.trainName=trainName;this.source=source;this.destination=destination;this.journeyDate=journeyDate;this.departure=departure;this.arrival=arrival;this.arrivalDayOffset=arrivalDayOffset;this.passengerName=passengerName;this.age=age;this.gender=gender;this.coach=coach;this.seatNumber=seatNumber;this.travelClass=travelClass;this.fare=fare;this.status=status;this.bookedAt=bookedAt;this.cancelledAt=cancelledAt;}
    public long getId(){return id;} public String getPnr(){return pnr;} public long getSeatId(){return seatId;} public long getJourneyId(){return journeyId;} public String getTrainNumber(){return trainNumber;} public String getTrainName(){return trainName;} public String getSource(){return source;} public String getDestination(){return destination;} public String getJourneyDate(){return journeyDate;} public String getDeparture(){return departure;} public String getArrival(){return arrival;} public int getArrivalDayOffset(){return arrivalDayOffset;} public String getPassengerName(){return passengerName;} public int getAge(){return age;} public String getGender(){return gender;} public String getCoach(){return coach;} public int getSeatNumber(){return seatNumber;} public TravelClass getTravelClass(){return travelClass;} public int getFare(){return fare;} public String getStatus(){return status;} public String getBookedAt(){return bookedAt;} public String getCancelledAt(){return cancelledAt;}
}
